const to = run.salary_coverage.to;
const contracts = get(ctx, 'reads.employee_contract', []).filter((contract) => {
	if (contract.effective_range.from > to) return false;
	const end = get(contract, 'effective_range.to', null);
	return end == null || end >= from;
});
// MOM: the LQS binds firms that hold work passes
