		entity_id: run.entity_id,
		employee_id: slip.employee_id,
		employment_id: slip.employment_id,
		title: ctx.lookup.title,
		due_on: to,
		occurrence_key: 'SG:LQS_WAGE_FLOOR:' + run.id + ':' + slip.employment_id
	}];
});

// CPF Board Step 2: in December or the last month of employment, re-calculate the AW ceiling on the actual OW. The balance holds AW paid, not AW charged, so the difference is raised rather than charged
const run = ctx.entry;
const to = run.salary_coverage.to;
const month = Number(to.slice(5, 7));
const contracts = get(ctx, 'reads.employee_contract', []);
const balances = get(ctx, 'reads.employee_balance', []);
return get(ctx, 'reads.payslip', []).flatMap((slip) => {
	if (!get(slip, 'breakdown.statutory', []).some((scheme) => scheme.code === 'CPF')) return [];
	const contract = contracts.find((row) => row.id === slip.employment_id);
	const leaving = String(get(contract, 'effective_range.to', ''));
	if (month !== 12 && (leaving === '' || leaving > month_end(to))) return [];
	const account = get(balances.find((row) => row.employee_id === slip.employee_id), 'account', {});
	const yearly = (code) => {
		const periods = get(account, 'pay.' + code, {});
		const key = 'SG.Y.' + to.slice(0, 4) + '-01-01';
		return Object.hasOwn(periods, key) ? Number(periods[key].total) : 0;
	};
	const ordinary = yearly('ORDINARY_WAGES');
	const additional = yearly('ADDITIONAL_WAGES') - ordinary;
	// no estimate can fall under the ceiling less twelve capped months: AW within it was charged in full
	if (additional <= ctx.lookup.annual_ceiling - 12 * ctx.lookup.ordinary_ceiling) return [];
	const started = String(get(contract, 'effective_range.from', ''));
	const opening = started.slice(0, 4) === to.slice(0, 4) ? Number(started.slice(5, 7)) : 1;
	const months = month - opening + 1;
	// a steady year to December: Step 1's estimate was the actual
	if (month === 12 && ordinary === Number(slip.ordinary_wages) * months) return [];
	const ceiling = ctx.lookup.annual_ceiling - Math.min(ordinary, ctx.lookup.ordinary_ceiling * months);
	return [{
		entity_id: run.entity_id,
		employee_id: slip.employee_id,
		employment_id: slip.employment_id,
		title: ctx.lookup.title + ': ceiling $' + ceiling.toFixed(2) + ', AW paid $' + additional.toFixed(2),
		due_on: add_days(month_end(to), ctx.lookup.offset_days),
		occurrence_key: 'SG:CPF_AW_YEAR_END_RECALCULATION:' + run.id + ':' + slip.employment_id
	}];
});

if (ctx.reads.obligation.length > 0) return [];
const row = first(ctx.reads.adhoc_catalog);
const refund = row.code.endsWith('_REFUND');
return [{
